Exception cause = new AsyncException('cause');
System.assertEquals('cause', cause.getMessage());
DmlException dmlFromCause = new DmlException(cause);
DmlException dmlFromMessage = new DmlException('dml');
DmlException dmlFromBoth = new DmlException('dml-both', cause);
System.assertEquals(cause, dmlFromCause.getCause());
System.assertEquals('dml', dmlFromMessage.getMessage());
System.assertEquals('dml-both', dmlFromBoth.getMessage());
System.assertEquals(cause, dmlFromBoth.getCause());
QueryException queryFromCause = new QueryException(cause);
QueryException queryFromMessage = new QueryException('query');
QueryException queryFromBoth = new QueryException('query-both', cause);
System.assertEquals(cause, queryFromCause.getCause());
System.assertEquals('query', queryFromMessage.getMessage());
System.assertEquals('query-both', queryFromBoth.getMessage());
System.assertEquals(cause, queryFromBoth.getCause());
SearchException search = new SearchException('search');
System.assertEquals('search', search.getMessage());

